// THE WORLD IN ONE DAY — 24 November 2026
// make.fun competition: news-image-20261124
// "Sum up 24 November's world news in one image"
//
// The program writes the entry image (1024x1024 PNG) to
// MAKEFUN_OUTPUT_DIR/entry.png (default ./output). Node 22, standard
// library only, no network access. The image bytes are embedded below
// as base64; the program is deterministic — every run writes the same
// bytes. The image was rendered from stories.json by render.py in this
// repository; every story in it was first reported on Tuesday
// 24 November 2026 (WIB day).

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const PNG_BASE64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "./output";
mkdirSync(outDir, { recursive: true });
const outPath = join(outDir, "entry.png");
writeFileSync(outPath, Buffer.from(PNG_BASE64, "base64"));
console.log(`wrote ${outPath}`);
